import{_ as o,o as a,c as r,a7 as s}from"./chunks/framework.Cv3pX6x0.js";const k=JSON.parse('{"title":"Resource Packs & Behaviour Packs","description":"How to load .zip and .mcpack resource packs on an Axolotl-PM server with resource_packs.yml. Behaviour packs are not supported.","frontmatter":{"title":"Resource Packs & Behaviour Packs","outline":"deep","description":"How to load .zip and .mcpack resource packs on an Axolotl-PM server with resource_packs.yml. Behaviour packs are not supported.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/resourcepacks"}]]},"headers":[],"relativePath":"docs/resourcepacks.md","filePath":"docs/resourcepacks.md","lastUpdated":1790689997000}'),c={name:"docs/resourcepacks.md"};function t(p,e,l,i,n,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="resource-packs-behaviour-packs" tabindex="-1">Resource Packs &amp; Behaviour Packs <a class="header-anchor" href="#resource-packs-behaviour-packs" aria-label="Permalink to &quot;Resource Packs &amp; Behaviour Packs&quot;">​</a></h1><p>Axolotl-PM has some support for resource packs.</p><p>Any number of valid resource packs may be loaded. However, per-world resource packs are not currently supported at the time of writing.</p><div class="danger custom-block"><p class="custom-block-title">Error</p><p>Behaviour packs are <strong>not</strong> supported.</p></div><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Resource packs which <strong>depend on behaviour packs</strong> may not work correctly. While Axolotl-PM will not prevent you loading such packs, it makes no attempt to validate dependencies and your game may experience errors or crashes when attempting to use them.</p></div><h2 id="installing-resource-packs" tabindex="-1">Installing resource packs <a class="header-anchor" href="#installing-resource-packs" aria-label="Permalink to &quot;Installing resource packs&quot;">​</a></h2><p>Resource packs to be loaded should be placed in the <code>resource_packs</code> folder of your server data.</p><p>Then, you will need to add them to the stack in the <code>resource_packs.yml</code> file (also located in the <code>resource_packs</code> folder).</p><h2 id="resource-stack" tabindex="-1">Resource stack <a class="header-anchor" href="#resource-stack" aria-label="Permalink to &quot;Resource stack&quot;">​</a></h2><p>This is a list of resource packs in <code>resource_packs.yml</code> that will be used by your server. It should contain a list of valid resource pack file names found in the <code>resource_packs</code> folder, including the file extension.</p><p>Resource packs are applied from bottom to top, similar to how they work in Minecraft itself. This means that resources at the top of the list will override resources lower down the list.</p><h2 id="supported-pack-formats" tabindex="-1">Supported pack formats <a class="header-anchor" href="#supported-pack-formats" aria-label="Permalink to &quot;Supported pack formats&quot;">​</a></h2><p>At the time of writing, the following types of resource pack are supported:</p><ul><li><code>.zip</code></li><li><code>.mcpack</code></li></ul><div class="danger custom-block"><p class="custom-block-title">Error</p><p>Unpacked (folder) resource packs are not currently supported.</p></div>',15)])])}const h=o(c,[["render",t]]);export{k as __pageData,h as default};
